 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            shape = [[grid[y][x] if (y, x) in set(cells) else 0 for x in range(minc, maxc + 1)] for y in range(minr, maxr + 1)]
            objects.append((color, shape))
    objects.sort(key=lambda item: item[0])
    out = [[0] * (3 * len(objects)) for _ in range(3)]
    for i, (color, shape) in enumerate(objects):
        for y in range(3):
            for x in range(3):
                out[y][3 * i + x] = shape[y][x]
    return out
